const $=id=>document.getElementById(id);
const CONFIG=window.KHADAMATI_CONFIG||{};
const BACKEND_READY=Boolean(CONFIG.supabaseUrl&&CONFIG.supabaseAnonKey&&window.supabase);
const sb=BACKEND_READY?window.supabase.createClient(CONFIG.supabaseUrl,CONFIG.supabaseAnonKey):null;
let sessionUser=null, selectedService='', selectedProvider=null, profileProvider=null, selectedRating=0, appliedCoupon=null;

const serviceInfo={'الاستعلامات':['🔎','الاستعلامات','استعلم عن حالة طلب أو معاملة وسجّل التفاصيل التي تريد متابعتها.'],'المدفوعات':['💳','المدفوعات','سجّل طلب مساعدة بخصوص فاتورة أو دفعة إلكترونية.'],'الطلبات':['📋','الطلبات','أنشئ طلب خدمة جديد وتابع حالته.'],'الخدمات الحكومية':['🏛️','الخدمات الحكومية','واجهة موحدة لاستقبال طلبات الخدمات الحكومية المتاحة لاحقاً عبر API.'],'الشكاوى':['📝','الشكاوى','قدّم شكوى مع وصف المشكلة ليتم تسجيلها ومتابعتها.'],'المساعدة':['💬','المساعدة والدعم','أرسل استفسارك أو المشكلة التي تواجهها وسجّلها كطلب دعم.']};
const publicServices={
 inquiries:{title:'الاستعلامات',icon:'🔎',desc:'استعلم عن حالة طلب أو معاملة وتابع التفاصيل بسهولة.'},
 payments:{title:'المدفوعات',icon:'💳',desc:'مساعدة في الفواتير والمدفوعات الإلكترونية ومتابعة العمليات.'},
 requests:{title:'الطلبات',icon:'📋',desc:'أنشئ طلب خدمة وتابع تنفيذه من مكان واحد.'},
 government:{title:'الخدمات الحكومية',icon:'🏛️',desc:'واجهة موحدة للوصول إلى الخدمات الحكومية المتاحة.'},
 complaints:{title:'الشكاوى',icon:'📝',desc:'قدّم شكوى وتابع حالتها والرد عليها.'},
 support:{title:'المساعدة والدعم',icon:'💬',desc:'احصل على المساعدة وسجّل مشكلة أو استفسار.'}
};
function updateSEO(title,desc){document.title=title+' | خدماتي';let m=document.querySelector('meta[name="description"]');if(m)m.setAttribute('content',desc);let og=document.querySelector('meta[property="og:title"]');if(og)og.setAttribute('content',title+' | خدماتي');let od=document.querySelector('meta[property="og:description"]');if(od)od.setAttribute('content',desc);}
function openPublicService(slug){const x=publicServices[slug];if(!x)return;trackEvent('service_view','service:'+slug);show('servicePage');$('publicServiceTitle').textContent=x.title;$('publicServiceIcon').textContent=x.icon;$('publicServiceDesc').textContent=x.desc;$('publicServiceLongDesc').textContent=x.desc+' يمكنك البدء بطلب الخدمة الآن، ثم متابعة الحالة والتواصل مع مقدم الخدمة من داخل المنصة.';updateSEO(x.title,x.desc);location.hash='service='+encodeURIComponent(slug);$('publicServiceRequestBtn').onclick=()=>{if(!user())return show('loginPage');openServiceModal(x.title)};$('serviceBackBtn').onclick=()=>{history.pushState({},'',location.pathname+location.search);updateSEO('خدماتي','خدماتي منصة عربية لطلب الخدمات، اكتشاف مقدمي الخدمات ومتابعة الطلبات بأمان.');showHome()};$('relatedServices').innerHTML=Object.entries(publicServices).filter(([k])=>k!==slug).slice(0,4).map(([k,v])=>`<button class="related-service" data-slug="${k}">${v.icon} ${escapeHtml(v.title)}</button>`).join('');document.querySelectorAll('.related-service').forEach(b=>b.onclick=()=>openPublicService(b.dataset.slug));}

function validPhone(p){return /^01[0-9]{9}$/.test(p)}
function setMsg(id,t,ok=false){const e=$(id);if(!e)return;e.textContent=t;e.classList.toggle('success-msg',ok)}
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2200)}
function show(page){['publicPage','loginPage','signupPage','homePage','providersPage','providerProfilePage','requestsPage','adminPage','walletPage','chatPage','servicePage','businessPage','referralPage','safetyPage','offersPage','executionPage','accountPage'].forEach(id=>$(id)?.classList.add('hidden'));$(page)?.classList.remove('hidden');$('logoutTop')?.classList.toggle('hidden',!['homePage','requestsPage','adminPage','providersPage','accountPage'].includes(page));window.dispatchEvent(new CustomEvent('khadamati:navigate',{detail:{page}}))}
function demoUser(){try{return JSON.parse(localStorage.getItem('khadamatiDemoUser')||'null')}catch{return null}}
function saveDemoUser(u){localStorage.setItem('khadamatiDemoUser',JSON.stringify(u))}
function clearDemo(){localStorage.removeItem('khadamatiDemoUser')}
function currentDemo(){const u=demoUser();return u?{id:'demo',name:u.name,phone:u.phone,role:u.role||'user'}:null}
const defaultProviders=[{id:'demo-p1',name:'أحمد للتصميم',verified:true,verification_status:'approved',category:'تصميم',description:'تصميم بوستات وهوية بصرية بشكل احترافي.',price:150,contact:'01011111111'},{id:'demo-p2',name:'تسويق أونلاين',category:'تسويق',description:'إدارة صفحات وإعلانات ممولة وخطة تسويق.',price:200,contact:'01022222222'},{id:'demo-p3',name:'محمود للبرمجة',category:'برمجة',description:'إنشاء مواقع وصفحات هبوط وتعديل المواقع.',price:300,contact:'01033333333'}];
function demoProviders(){try{return JSON.parse(localStorage.getItem('khadamatiProviders')||'null')||defaultProviders}catch{return defaultProviders}}
function saveProviders(a){localStorage.setItem('khadamatiProviders',JSON.stringify(a))}
function user(){return BACKEND_READY?sessionUser:currentDemo()}
function statusClass(s){return s==='تم التنفيذ'?'done':s==='جاري التنفيذ'?'working':s==='ملغي'?'cancelled':'pending'}
function formatDate(v){try{return new Intl.DateTimeFormat('ar-EG',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v))}catch{return v}}
function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}

function verificationBadge(p){if(p?.verified)return '<span class="verified-badge">🛡️ موثّق</span>';if(p?.verification_status==='pending')return '<span class="verification-pending">⏳ التوثيق قيد المراجعة</span>';return ''}
function demoTrust(){try{return JSON.parse(localStorage.getItem('khadamatiTrust')||'{}')}catch{return {}}}
function saveDemoTrust(x){localStorage.setItem('khadamatiTrust',JSON.stringify(x))}
function trustScore(p){const rating=Math.max(0,Math.min(5,Number(p?.avg_rating||0)));const reviews=Math.min(5,Number(p?.review_count||0));const completed=Math.min(5,Number(p?.completed||0));let score=35+rating*9+reviews*2+completed*2+(p?.verified?10:0);const t=demoTrust()[String(p?.id)]||{};score-=Math.min(25,Number(t.risk_penalty||0));return Math.max(0,Math.min(100,Math.round(score)))}
function trustLevel(score){return score>=85?'ممتاز':score>=70?'موثوق':score>=50?'جيد':'يحتاج مراجعة'}
function trustBadge(p){const sc=trustScore(p);return `<span class="trust-badge">🛡️ ثقة ${sc}% · ${trustLevel(sc)}</span>`}

function demoVerification(){try{return JSON.parse(localStorage.getItem('khadamatiVerification')||'[]')}catch{return []}}
function saveDemoVerification(a){localStorage.setItem('khadamatiVerification',JSON.stringify(a.slice(0,100)))}

async function trackEvent(eventType,page,metadata={}){try{if(BACKEND_READY&&sessionUser)await sb.from('platform_events').insert({user_id:sessionUser.id,event_type:eventType,page,metadata});}catch{}}
const notificationIcons={request:'📋',status:'🔄',payment:'💳',earning:'📈',refund:'↩️',system:'🔔'};
function demoNotifications(){try{return JSON.parse(localStorage.getItem('khadamatiNotifications')||'[]')}catch{return []}}
function saveDemoNotifications(a){localStorage.setItem('khadamatiNotifications',JSON.stringify(a.slice(0,100)))}
function addDemoNotification(title,body,type='system'){const a=demoNotifications();a.unshift({id:'dn-'+Date.now()+'-'+Math.random().toString(16).slice(2),title,body,type,read:false,created_at:new Date().toISOString()});saveDemoNotifications(a);renderNotifications()}
async function loadNotifications(){
  if(!BACKEND_READY) return demoNotifications();
  const {data,error}=await sb.from('notifications').select('id,title,body,type,read,created_at').order('created_at',{ascending:false}).limit(50);
  if(error) throw error; return data||[];
}
function notificationHtml(n){const icon=notificationIcons[n.type]||'🔔';return `<article class="notification-item ${n.read?'':'unread'}" data-notification-id="${escapeHtml(n.id)}"><span class="notification-icon">${icon}</span><div><b>${escapeHtml(n.title)}</b><p>${escapeHtml(n.body)}</p><small>${formatDate(n.created_at||n.createdAt)}</small>${n.read?'':'<div class="notification-actions"><button class="secondary mark-one" data-id="'+escapeHtml(n.id)+'">تحديد كمقروء</button></div>'}</div></article>`}
async function renderNotifications(){
  if(!user()) return;
  try{const list=await loadNotifications(); const unread=list.filter(n=>!n.read).length;
    $('notificationsCount').textContent=unread; $('notifDot').style.display=unread?'block':'none'; $('notifBadge').textContent=unread; $('notifBadge').classList.toggle('hidden',!unread);
    const home=$('notificationsList'); if(home) home.innerHTML=list.length?list.slice(0,5).map(notificationHtml).join(''):'<div class="notification-empty"><div>🔔</div>لا توجد إشعارات جديدة.</div>';
    const modal=$('notificationsModalList'); if(modal) modal.innerHTML=list.length?list.map(notificationHtml).join(''):'<div class="notification-empty"><div>🔔</div>لا توجد إشعارات.</div>';
    document.querySelectorAll('.mark-one').forEach(b=>b.onclick=()=>markNotificationRead(b.dataset.id));
  }catch(e){if($('notificationsList'))$('notificationsList').innerHTML='<div class="notification-empty">تعذر تحميل الإشعارات حالياً.</div>'}
}
async function markNotificationRead(id){try{async function showPublic(){show('publicPage');try{const list=await loadProviders();const top=list.slice(0,3);$('publicProvidersList').innerHTML=top.length?top.map(p=>`<article class="provider-card"><div class="provider-avatar">🧑‍💼</div><span class="provider-category">${escapeHtml(p.category)}</span>${verificationBadge(p)}<h3>${escapeHtml(p.name)}</h3><p class="provider-desc">${escapeHtml(p.description)}</p><div class="provider-price">${escapeHtml(p.price)} جنيه <small>يبدأ من</small></div><div class="provider-actions"><button class="secondary public-profile" data-id="${escapeHtml(p.id)}">عرض الملف</button></div></article>`).join(''):'<div class="empty-state"><div>🧑‍💼</div><h3>لا يوجد مقدمو خدمات بعد</h3><p>كن أول من يضيف خدمته.</p></div>';document.querySelectorAll('.public-profile').forEach(b=>b.onclick=()=>showProviderProfile(b.dataset.id))}catch(e){$('publicProvidersList').innerHTML='<div class="empty-state"><h3>تعذر تحميل مقدمي الخدمات</h3></div>'}}
$('publicProvidersBtn')?.addEventListener('click',showProviders);$('publicSeeAll')?.addEventListener('click',showProviders);$('publicLoginBtn')?.addEventListener('click',()=>show('loginPage'));document.querySelectorAll('.service[data-service-slug]').forEach(b=>b.addEventListener('click',()=>openPublicService(b.dataset.serviceSlug)));

function handlePublicHash(){const sm=location.hash.match(/^#service=(.+)$/);if(sm){openPublicService(decodeURIComponent(sm[1]));return true}const m=location.hash.match(/^#provider=(.+)$/);if(m){showProviderProfile(decodeURIComponent(m[1]));return true}return false}
if(BACKEND_READY){const {error}=await sb.from('notifications').update({read:true}).eq('id',id).eq('user_id',sessionUser.id);if(error)throw error}else{const a=demoNotifications();const n=a.find(x=>String(x.id)===String(id));if(n)n.read=true;saveDemoNotifications(a)}renderNotifications()}catch(e){toast('تعذر تحديث الإشعار')}}
async function markAllNotificationsRead(){try{async function showPublic(){show('publicPage');try{const list=await loadProviders();const top=list.slice(0,3);$('publicProvidersList').innerHTML=top.length?top.map(p=>`<article class="provider-card"><div class="provider-avatar">🧑‍💼</div><span class="provider-category">${escapeHtml(p.category)}</span>${verificationBadge(p)}<h3>${escapeHtml(p.name)}</h3><p class="provider-desc">${escapeHtml(p.description)}</p><div class="provider-price">${escapeHtml(p.price)} جنيه <small>يبدأ من</small></div><div class="provider-actions"><button class="secondary public-profile" data-id="${escapeHtml(p.id)}">عرض الملف</button></div></article>`).join(''):'<div class="empty-state"><div>🧑‍💼</div><h3>لا يوجد مقدمو خدمات بعد</h3><p>كن أول من يضيف خدمته.</p></div>';document.querySelectorAll('.public-profile').forEach(b=>b.onclick=()=>showProviderProfile(b.dataset.id))}catch(e){$('publicProvidersList').innerHTML='<div class="empty-state"><h3>تعذر تحميل مقدمي الخدمات</h3></div>'}}
$('publicProvidersBtn')?.addEventListener('click',showProviders);$('publicSeeAll')?.addEventListener('click',showProviders);$('publicLoginBtn')?.addEventListener('click',()=>show('loginPage'));document.querySelectorAll('.service[data-service-slug]').forEach(b=>b.addEventListener('click',()=>openPublicService(b.dataset.serviceSlug)));

function handlePublicHash(){const sm=location.hash.match(/^#service=(.+)$/);if(sm){openPublicService(decodeURIComponent(sm[1]));return true}const m=location.hash.match(/^#provider=(.+)$/);if(m){showProviderProfile(decodeURIComponent(m[1]));return true}return false}
if(BACKEND_READY){const {error}=await sb.from('notifications').update({read:true}).eq('user_id',sessionUser.id).eq('read',false);if(error)throw error}else{const a=demoNotifications().map(x=>({...x,read:true}));saveDemoNotifications(a)}toast('تمت قراءة كل الإشعارات ✓');renderNotifications()}catch(e){toast('تعذر تحديث الإشعارات')}}
function openNotifications(){if(!user())return show('loginPage');$('notificationsModal').classList.remove('hidden');$('notificationsModal').setAttribute('aria-hidden','false');renderNotifications()}
function closeNotifications(){$('notificationsModal').classList.add('hidden');$('notificationsModal').setAttribute('aria-hidden','true')}
function seedDemoNotifications(){if(!BACKEND_READY&&!localStorage.getItem('khadamatiNotifications')){saveDemoNotifications([{id:'welcome-1',title:'مرحباً بك في خدماتي',body:'يمكنك الآن استكشاف الخدمات ومقدمي الخدمات من مكان واحد.',type:'system',read:false,created_at:new Date().toISOString()},{id:'secure-1',title:'نظام الوساطة جاهز',body:'يتم حجز مبلغ الطلب حتى تأكيد استلام الخدمة.',type:'payment',read:false,created_at:new Date(Date.now()-60000).toISOString()}])}}
function subscribeNotifications(){if(!BACKEND_READY||!sessionUser)return null;return sb.channel('khadamati-notifications-'+sessionUser.id).on('postgres_changes',{event:'INSERT',schema:'public',table:'notifications',filter:'user_id=eq.'+sessionUser.id},payload=>{toast('🔔 '+(payload.new?.title||'لديك إشعار جديد'));renderNotifications()}).on('postgres_changes',{event:'UPDATE',schema:'public',table:'notifications',filter:'user_id=eq.'+sessionUser.id},()=>renderNotifications()).subscribe()}
let notificationChannel=null;

async function loadProfile(){if(!BACKEND_READY)return currentDemo();const {data:{user:u}}=await sb.auth.getUser();if(!u)return null;const {data:p,error}=await sb.from('profiles').select('id,full_name,phone,role').eq('id',u.id).single();if(error)throw error;sessionUser={id:p.id,name:p.full_name,phone:p.phone,role:p.role};return sessionUser}
async function loadRequests(){if(!BACKEND_READY){return demoUser()?.requestList||[]}const {data,error}=await sb.from('service_requests').select('id,service,note,status,created_at,provider_id,provider_price,platform_fee,payment_status,provider_net').order('created_at',{ascending:false});if(error)throw error;return data.map(r=>({...r,createdAt:r.created_at,providerId:r.provider_id,providerPrice:r.provider_price,platformFee:r.platform_fee,paymentStatus:r.payment_status,providerNet:r.provider_net}))}
async function createRequest(service,note,providerId=null){if(!BACKEND_READY){const u=demoUser()||{name:'أحمد',phone:'01000000000',role:'user'};u.requestList=u.requestList||[];const p=providerId?demoProviders().find(x=>String(x.id)===String(providerId)):null;const r={id:'KHD-'+Date.now().toString().slice(-6),service,note,providerId,providerName:p?.name||'',providerPrice:p?.price||0,platformFee:p?Number(p.price)*0.10:0,providerNet:p?Number(p.price)*0.90:0,paymentStatus:p?'pending':'not_required',createdAt:new Date().toISOString(),status:'قيد المراجعة',rated:false};u.requestList.unshift(r);saveDemoUser(u);trackEvent('request_created','request:'+r.id,{service,provider_id:providerId});addDemoNotification('تم إنشاء طلب جديد','تم تسجيل طلبك '+r.id+' بنجاح.','request');return r}const p=providerId?await getProvider(providerId):null;const price=p?.price||null;const fee=p?Number(price)*Number(p.commission_rate||10)/100:0;const {data,error}=await sb.from('service_requests').insert({user_id:sessionUser.id,service,note,provider_id:providerId||null,provider_price:price,platform_fee:fee,provider_net:p?Number(price)-fee:0,payment_status:p?'pending':'not_required'}).select('id,service,note,status,created_at,provider_id,provider_price,platform_fee,provider_net,payment_status').single();if(error)throw error;trackEvent('request_created','request:'+data.id,{service,provider_id:providerId});return data}
async function showHome(){const u=user();if(!u)return show('loginPage');show('homePage');$('welcomeName').textContent=u.name||'بك';try{const list=await loadRequests();$('requestsCount').textContent=list.length;renderRequestsPreview(list);updateWalletMini();renderNotifications()}catch(e){toast('تعذر تحميل الطلبات')} }
async function showRequests(){const u=user();if(!u)return show('loginPage');show('requestsPage');try{renderRequests(await loadRequests())}catch(e){setMsg('requestPageMsg','تعذر تحميل الطلبات حالياً.')}}
function renderRequests(list){const box=$('requestsList');$('requestsPageCount').textContent=list.length;if(!list.length){box.innerHTML='<div class="empty-state"><div>📋</div><h3>لا توجد طلبات حتى الآن</h3><p>ابدأ من الخدمات الرئيسية وأنشئ أول طلب لك.</p><button class="primary" id="emptyHomeBtn">استكشاف الخدمات</button></div>';$('emptyHomeBtn').onclick=showHome;return}box.innerHTML=list.map(r=>`<article class="request-card"><div class="request-top"><span class="request-id">${escapeHtml(r.id)}</span><span class="status ${statusClass(r.status)}">${escapeHtml(r.status||'قيد المراجعة')}</span></div><div class="request-service">${serviceInfo[r.service]?.[0]||'📋'} <b>${escapeHtml(r.service)}</b></div><p>${escapeHtml(r.note)}</p><small>${formatDate(r.createdAt)}</small>${r.paymentStatus==='held'?`<div class="escrow-note">🔐 المبلغ محجوز حتى تأكيد استلامك للخدمة.</div><button class="primary release-payment" data-request='${escapeHtml(JSON.stringify(r))}' ${r.status!=='تم التنفيذ'?'disabled':''}>${r.status==='تم التنفيذ'?'✅ تأكيد استلام الخدمة':'⏳ بانتظار اكتمال الخدمة'}</button>`:''}${r.paymentStatus==='released'?`<div class="escrow-note success-msg">✅ تم تحرير المبلغ لمقدم الخدمة.</div>`:''}${r.paymentStatus==='refunded'?`<div class="escrow-note success-msg">↩️ تم استرداد المبلغ إلى محفظتك.</div>`:''}${r.providerId?`<button class="secondary chat-request" data-request='${escapeHtml(JSON.stringify(r))}'>💬 محادثة مع مقدم الخدمة</button>`:''}${r.providerId&&r.status==='تم التنفيذ'&&!r.rated?`<button class="secondary rate-request" data-request='${escapeHtml(JSON.stringify(r))}'>⭐ قيّم مقدم الخدمة</button>`:''}</article>`).join('');bindRatingButtons()}
function bindRatingButtons(){document.querySelectorAll('.rate-request').forEach(b=>b.onclick=()=>openRatingForRequest(JSON.parse(b.dataset.request)));document.querySelectorAll('.release-payment').forEach(b=>b.onclick=()=>releasePayment(JSON.parse(b.dataset.request)));document.querySelectorAll('.chat-request').forEach(b=>b.onclick=()=>openChat(JSON.parse(b.dataset.request)))}
function renderRequestsPreview(list){const box=$('requestsPreview');if(!list.length){box.innerHTML='<p class="muted">لا توجد طلبات بعد. ابدأ باختيار خدمة من الأعلى.</p>';return}box.innerHTML=list.slice(0,3).map(r=>`<div class="mini-request"><span>${serviceInfo[r.service]?.[0]||'📋'}</span><div><b>${escapeHtml(r.service)}</b><small>${escapeHtml(r.status||'قيد المراجعة')} · ${formatDate(r.createdAt)}</small></div></div>`).join('')}

let activeChatRequest=null, chatChannel=null;
function demoChats(){try{return JSON.parse(localStorage.getItem('khadamatiChats')||'{}')}catch{return {}}}
function saveDemoChats(x){localStorage.setItem('khadamatiChats',JSON.stringify(x))}
function chatKey(rid){return String(rid)}
function chatBubble(m){const mine=BACKEND_READY?m.sender_id===sessionUser?.id:m.sender_id==='me';return `<div class="chat-row ${mine?'mine':'theirs'}"><div class="chat-bubble"><p>${escapeHtml(m.body)}</p><small>${formatDate(m.created_at||m.createdAt)}</small></div></div>`}
async function loadChatMessages(requestId){
  if(!BACKEND_READY){const all=demoChats();return all[chatKey(requestId)]||[]}
  const {data,error}=await sb.from('service_messages').select('id,request_id,sender_id,receiver_id,body,created_at').eq('request_id',Number(requestId)).order('created_at',{ascending:true});
  if(error)throw error;return data||[]
}
async function renderChat(){if(!activeChatRequest)return;try{const list=await loadChatMessages(activeChatRequest.id);$('chatMessages').innerHTML=list.length?list.map(chatBubble).join(''):'<div class="chat-empty">💬<b>ابدأ المحادثة</b><span>اكتب تفاصيل أو أسئلة تخص هذا الطلب.</span></div>';$('chatMessages').scrollTop=$('chatMessages').scrollHeight}catch(e){$('chatMessages').innerHTML='<div class="chat-empty">تعذر تحميل الرسائل حالياً.</div>'}}
