async function loadAdminData(){
  if(!BACKEND_READY){
    const u=demoUser()||{}; const requests=(u.requestList||[]).map(r=>({...r,userName:u.name,userPhone:u.phone}));
    const providers=demoProviders().map(p=>({...p,completed:requests.filter(r=>String(r.providerId)===String(p.id)&&r.status==='تم التنفيذ').length}));
    const transactions=JSON.parse(localStorage.getItem('khadamatiWalletTx')||'[]');
    return {requests,users:u.name?[{id:'demo',full_name:u.name,phone:u.phone,role:u.role||'user'}]:[],providers,withdrawals:JSON.parse(localStorage.getItem('khadamatiWithdrawals')||'[]'),transactions};
  }
  const [rq,us,pv,wd,tx]=await Promise.all([
    sb.from('service_requests').select('id,user_id,service,note,status,created_at,provider_id,provider_price,platform_fee,provider_net,payment_status,profiles(full_name,phone),providers(name)').order('created_at',{ascending:false}),
    sb.from('profiles').select('id,full_name,phone,role,created_at').order('created_at',{ascending:false}),
    sb.from('providers').select('id,user_id,name,category,description,price,active,commission_rate,verified,verification_status').order('created_at',{ascending:false}),
    sb.from('withdrawal_requests').select('id,user_id,amount,method,status,created_at,profiles(full_name,phone)').order('created_at',{ascending:false}),
    sb.from('wallet_transactions').select('id,user_id,type,amount,request_id,note,created_at,profiles(full_name,phone)').order('created_at',{ascending:false}).limit(100)
  ]);
  for(const x of [rq,us,pv,wd,tx])if(x.error)throw x.error;
  return {requests:(rq.data||[]).map(x=>({...x,userName:x.profiles?.full_name||'',userPhone:x.profiles?.phone||'',providerName:x.providers?.name||'',createdAt:x.created_at,providerPrice:x.provider_price,platformFee:x.platform_fee,paymentStatus:x.payment_status,providerNet:x.provider_net})),users:us.data||[],providers:pv.data||[],withdrawals:wd.data||[],transactions:tx.data||[]};
}
