// V5.4 — نظام الثقة والتحقق
let verificationProvider=null;
function openVerificationModal(){if(!user())return show('loginPage');if(!profileProvider)return toast('افتح ملف مقدم الخدمة أولاً');verificationProvider=profileProvider;$('verificationType').value='id';$('verificationFile').value='';$('verificationNote').value='';setMsg('verificationMsg','');$('verificationModal').classList.remove('hidden');$('verificationModal').setAttribute('aria-hidden','false')}
function closeVerificationModal(){$('verificationModal').classList.add('hidden');$('verificationModal').setAttribute('aria-hidden','true')}
async function submitVerification(){if(!verificationProvider||!user())return;const file=$('verificationFile').files?.[0];const type=$('verificationType').value;const note=$('verificationNote').value.trim();if(!file)return setMsg('verificationMsg','اختر ملف المستند أولاً.');if(file.size>8*1024*1024)return setMsg('verificationMsg','حجم الملف يجب ألا يتجاوز 8 ميجابايت.');try{$('submitVerification').disabled=true;setMsg('verificationMsg','جاري إرسال الطلب...');if(!BACKEND_READY){const a=demoVerification();a.unshift({id:'dv-'+Date.now(),providerId:verificationProvider.id,userId:user().id,providerName:verificationProvider.name,documentType:type,fileName:file.name,note,status:'pending',createdAt:new Date().toISOString()});saveDemoVerification(a);const ps=demoProviders().map(p=>String(p.id)===String(verificationProvider.id)?{...p,verification_status:'pending'}:p);saveProviders(ps);setMsg('verificationMsg','تم إرسال طلب التوثيق للمراجعة ✅',true);addDemoNotification('طلب التوثيق','تم إرسال طلب توثيق مقدم الخدمة للمراجعة.','system');setTimeout(()=>{closeVerificationModal();showProviderProfile(verificationProvider.id)},600);return}
const uid=sessionUser.id;const safeName=file.name.replace(/[^a-zA-Z0-9._-]/g,'_');const path=`${uid}/${Date.now()}-${safeName}`;const up=await sb.storage.from('verification-docs').upload(path,file,{upsert:false,contentType:file.type||undefined});if(up.error)throw up.error;const ins=await sb.from('provider_verification_requests').insert({provider_id:Number(verificationProvider.id),user_id:uid,document_type:type,document_path:path,note:note||null,status:'pending'});if(ins.error)throw ins.error;await sb.from('providers').update({verification_status:'pending'}).eq('id',Number(verificationProvider.id)).eq('user_id',uid);setMsg('verificationMsg','تم إرسال طلب التوثيق للمراجعة ✅',true);setTimeout(()=>{closeVerificationModal();showProviderProfile(verificationProvider.id)},600)}catch(e){setMsg('verificationMsg','تعذر إرسال الطلب. '+(e.message||''))}finally{$('submitVerification').disabled=false}}
async function loadVerificationRequests(){if(!BACKEND_READY)return demoVerification();const {data,error}=await sb.from('provider_verification_requests').select('id,provider_id,user_id,document_type,document_path,note,status,created_at,reviewed_at,providers(name),profiles(full_name,phone)').order('created_at',{ascending:false});if(error)throw error;const rows=data||[];for(const r of rows){if(r.document_path){const su=await sb.storage.from('verification-docs').createSignedUrl(r.document_path,300);r.document_url=su.data?.signedUrl||''}}return rows}
async function reviewVerification(id,providerId,status){try{if(!BACKEND_READY){const a=demoVerification();const x=a.find(v=>String(v.id)===String(id));if(x){x.status=status;x.reviewedAt=new Date().toISOString();if(status==='approved'){const ps=demoProviders().map(p=>String(p.id)===String(providerId)?{...p,verified:true,verification_status:'approved'}:p);saveProviders(ps)}else if(status==='rejected'){const ps=demoProviders().map(p=>String(p.id)===String(providerId)?{...p,verified:false,verification_status:'rejected'}:p);saveProviders(ps)}}saveDemoVerification(a);toast(status==='approved'?'تم توثيق مقدم الخدمة 🛡️':'تم رفض طلب التوثيق');return renderAdmin()}const {data,error}=await sb.rpc('admin_review_verification',{p_request_id:Number(id),p_status:status});if(error)throw error;toast(status==='approved'?'تم توثيق مقدم الخدمة 🛡️':'تم تحديث حالة التوثيق');renderAdmin()}catch(e){toast('تعذر تحديث طلب التوثيق')}}
async function renderAdminVerification(){const box=$('adminVerificationList');if(!box)return;try{const list=await loadVerificationRequests();const q=($('adminSearch')?.value||'').trim().toLowerCase();const f=list.filter(x=>[x.providers?.name,x.profiles?.full_name,x.profiles?.phone,x.document_type,x.status].some(v=>String(v||'').toLowerCase().includes(q)));box.innerHTML=f.length?f.map(x=>`<article class="verification-admin-row"><div><b>🛡️ ${escapeHtml(x.providers?.name||x.providerName||'مقدم خدمة')}</b><small>${escapeHtml(x.profiles?.full_name||'')} · ${escapeHtml(x.profiles?.phone||'')} · ${escapeHtml(x.document_type||'')}</small><small>${escapeHtml(x.note||'بدون ملاحظة')} · ${formatDate(x.created_at||x.createdAt)}</small></div><a class="secondary doc-link" ${x.document_url?'href="'+escapeHtml(x.document_url)+'"':''} target="_blank" rel="noopener">${x.document_path?'📎 المستند':'بدون ملف'}</a><select class="verification-status" data-id="${escapeHtml(x.id)}" data-provider="${escapeHtml(x.provider_id)}"><option value="pending" ${x.status==='pending'?'selected':''}>قيد المراجعة</option><option value="approved" ${x.status==='approved'?'selected':''}>مقبول</option><option value="rejected" ${x.status==='rejected'?'selected':''}>مرفوض</option></select></article>`).join(''):'<div class="empty-state"><div>🛡️</div><h3>لا توجد طلبات توثيق</h3><p>طلبات التوثيق الجديدة ستظهر هنا.</p></div>';box.querySelectorAll('.verification-status').forEach(s=>s.onchange=()=>reviewVerification(s.dataset.id,s.dataset.provider,s.value))}catch(e){box.innerHTML='<div class="empty-state"><h3>تعذر تحميل طلبات التوثيق</h3></div>'}}
$('closeVerification')?.addEventListener('click',closeVerificationModal);$('verificationModal')?.addEventListener('click',e=>{if(e.target.id==='verificationModal')closeVerificationModal()});$('submitVerification')?.addEventListener('click',submitVerification);

// V3.5 — مساعد خدماتي الذكي (محرك ترشيح محلي آمن، بدون مفاتيح سرية داخل المتصفح)
const aiState={step:0,answers:{}};
const aiQuestions=[
 {key:'goal',title:'إيه اللي محتاج تعمله؟',options:[['website','عمل موقع أو صفحة هبوط'],['marketing','تسويق أو إعلانات'],['design','تصميم صور أو هوية'],['code','برمجة أو تعديل برنامج'],['maintenance','صيانة أو إصلاح'],['other','خدمة أخرى']]},
 {key:'budget',title:'ميزانيتك التقريبية؟',options:[['low','حتى 200 جنيه'],['mid','من 200 إلى 500 جنيه'],['high','أكثر من 500 جنيه'],['unknown','مش عارف لسه']]},
 {key:'speed',title:'إمتى محتاج الخدمة؟',options:[['urgent','بسرعة'],['normal','خلال أيام'],['flex','مش مستعجل']]},
];
function openAiAssistant(){if(!user())return show('loginPage');aiState.step=0;aiState.answers={};$('aiResult').classList.add('hidden');$('aiNextBtn').textContent='التالي';$('aiBackBtn').classList.add('hidden');$('aiModal').classList.remove('hidden');$('aiModal').setAttribute('aria-hidden','false');renderAiStep()}
function closeAiAssistant(){$('aiModal').classList.add('hidden');$('aiModal').setAttribute('aria-hidden','true')}
function renderAiStep(){const q=aiQuestions[aiState.step];$('aiStepHint').textContent=`السؤال ${aiState.step+1} من ${aiQuestions.length}`;$('aiWizard').innerHTML=`<div class="ai-question"><h3>${escapeHtml(q.title)}</h3>${q.options.map(([v,l])=>`<label class="ai-option ${aiState.answers[q.key]===v?'selected':''}"><input type="radio" name="ai-${q.key}" value="${v}" ${aiState.answers[q.key]===v?'checked':''}> <span>${escapeHtml(l)}</span></label>`).join('')}</div>`;document.querySelectorAll('.ai-option').forEach(o=>o.onclick=()=>{document.querySelectorAll('.ai-option').forEach(x=>x.classList.remove('selected'));o.classList.add('selected');o.querySelector('input').checked=true});$('aiBackBtn').classList.toggle('hidden',aiState.step===0)}
function aiCategory(goal){return goal==='marketing'?'تسويق':goal==='design'?'تصميم':goal==='code'||goal==='website'?'برمجة':goal==='maintenance'?'صيانة':'أخرى'}
function aiScoreProvider(p,a){let score=0;const cat=aiCategory(a.goal);if(p.category===cat)score+=60;if(a.budget==='low'&&Number(p.price)<=200)score+=25;if(a.budget==='mid'&&Number(p.price)<=500)score+=20;if(a.budget==='high')score+=15;if(a.budget==='unknown')score+=10;if(a.speed==='urgent')score+=5;score+=Math.min(10,Number(p.rating||0)*2);return score}
function aiRecommend(){const a=aiState.answers,cat=aiCategory(a.goal),providers=demoProviders().map(p=>({...p,score:aiScoreProvider(p,a)})).sort((x,y)=>y.score-x.score);const top=providers.filter(p=>p.category===cat).slice(0,3);const picks=(top.length?top:providers).slice(0,3);$('aiStepHint').textContent='الترشيح جاهز';$('aiWizard').innerHTML='';$('aiNextBtn').textContent='ابدأ طلبًا جديدًا';$('aiResult').classList.remove('hidden');$('aiResult').innerHTML=`<h3>🎯 أنسب تصنيف لك: ${escapeHtml(cat)}</h3><p class="muted">بناءً على هدفك وميزانيتك والسرعة، هذه أفضل الترشيحات المتاحة الآن.</p><div class="ai-recommendations">${picks.map(p=>`<div class="ai-provider"><div><b>${escapeHtml(p.name)}</b><small>${escapeHtml(p.category)} · يبدأ من ${Number(p.price||0)} جنيه${p.rating?' · ⭐ '+Number(p.rating).toFixed(1):''}</small></div><button class="secondary ai-pick" data-id="${escapeHtml(p.id)}">عرض المقدم</button></div>`).join('')}</div><p class="muted" style="margin-bottom:0">ملاحظة: هذا الترشيح آلي داخل الموقع، ويمكن لاحقًا ربطه بخدمة ذكاء اصطناعي حقيقية من خادم آمن.</p>`;document.querySelectorAll('.ai-pick').forEach(b=>b.onclick=()=>{closeAiAssistant();openProviderProfile(b.dataset.id)})}
function aiNext(){if(aiState.step<aiQuestions.length){const q=aiQuestions[aiState.step],sel=document.querySelector(`input[name="ai-${q.key}"]:checked`);if(!sel)return toast('اختار إجابة الأول 👌');aiState.answers[q.key]=sel.value;if(aiState.step===aiQuestions.length-1){aiState.step=aiQuestions.length;aiRecommend()}else{aiState.step++;renderAiStep()}}else{closeAiAssistant();show('providersPage');renderProviders()} }
function aiBack(){if(aiState.step>0&&aiState.step<aiQuestions.length){aiState.step--;renderAiStep()}}

// V4.2 — نظام الإحالة والمشاركة
function referralCode(){const u=user()||{};const raw=String(u.id||u.phone||'demo').replace(/\D/g,'').slice(-6).padStart(6,'0');return 'KH-'+raw}
function referralLink(){return location.origin+location.pathname+'#ref='+encodeURIComponent(referralCode())}
function referralData(){const key='khadamatiReferral_'+referralCode();return JSON.parse(localStorage.getItem(key)||'{"invites":0,"qualified":0,"rewards":0}')}
function saveReferralData(d){localStorage.setItem('khadamatiReferral_'+referralCode(),JSON.stringify(d))}
async function renderReferral(){if(!user())return show('loginPage');show('referralPage');const code=referralCode();$('myReferralCode').textContent=code;$('myReferralLink').value=referralLink();let d=referralData();if(BACKEND_READY){try{const {data,error}=await sb.rpc('my_referral_stats');if(!error&&data){const x=Array.isArray(data)?data[0]:data;if(x){d={invites:Number(x.invites||0),qualified:Number(x.qualified||0),rewards:Number(x.rewards||0)}}}}catch{}}$('refInvites').textContent=d.invites;$('refQualified').textContent=d.qualified;$('refRewards').textContent=money(d.rewards)}
$('referralBtn')?.addEventListener('click',renderReferral);$('referralBackBtn')?.addEventListener('click',showHome);$('copyReferralBtn')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('myReferralCode').textContent);toast('تم نسخ كود الإحالة ✓')}catch{toast('الكود: '+$('myReferralCode').textContent)}});$('shareReferralBtn')?.addEventListener('click',async()=>{const url=referralLink();try{if(navigator.share)await navigator.share({title:'خدماتي',text:'جرّب خدماتي من خلال رابط دعوتي 🎁',url});else{await navigator.clipboard.writeText(url);toast('تم نسخ رابط الدعوة ✓')}}catch{}});$('demoReferralBtn')?.addEventListener('click',()=>{const d=referralData();d.invites++;d.qualified++;d.rewards+=25;saveReferralData(d);toast('تمت إضافة دعوة تجريبية +25 جنيه 🎁');renderReferral()});
$('aiAssistantBtn')?.addEventListener('click',openAiAssistant);$('closeAiModal')?.addEventListener('click',closeAiAssistant);$('aiNextBtn')?.addEventListener('click',aiNext);$('aiBackBtn')?.addEventListener('click',aiBack);
document.querySelectorAll('.service[data-service-slug]').forEach(b=>b.addEventListener('click',()=>openPublicService(b.dataset.serviceSlug)));
document.querySelectorAll('.admin-tab').forEach(t=>t.onclick=()=>{document.querySelectorAll('.admin-tab').forEach(x=>x.classList.remove('active'));t.classList.add('active');renderAdmin()});$('adminSearch').oninput=renderAdmin;

