/* V5.5 — نظام مكافحة الاحتيال والنزاعات */
function demoSafety(){try{return JSON.parse(localStorage.getItem('khadamatiSafety')||'[]')}catch{return []}}
function saveDemoSafety(a){localStorage.setItem('khadamatiSafety',JSON.stringify(a.slice(0,100)))}
let safetyMode='report';
function openSafetyModal(mode='report'){if(!user())return show('loginPage');safetyMode=mode;$('safetyModalTitle').textContent=mode==='dispute'?'فتح نزاع':'إرسال بلاغ';$('safetyMsg').textContent='';$('safetyModal').classList.remove('hidden');$('safetyModal').setAttribute('aria-hidden','false')}
function closeSafetyModal(){$('safetyModal').classList.add('hidden');$('safetyModal').setAttribute('aria-hidden','true')}
async function submitSafety(){const u=user();if(!u)return show('loginPage');const providerId=$('safetyProviderId').value.trim();const requestId=$('safetyRequestId').value.trim();const reason=$('safetyReason').value;const details=$('safetyDetails').value.trim();if(details.length<10)return setMsg('safetyMsg','اكتب تفاصيل أوضح (10 أحرف على الأقل).');try{if(BACKEND_READY){const table=safetyMode==='dispute'?'disputes':'reports';const payload=safetyMode==='dispute'?{user_id:u.id,request_id:requestId?Number(requestId):null,provider_id:providerId?Number(providerId):null,reason,details}:{reporter_id:u.id,provider_id:providerId?Number(providerId):null,request_id:requestId?Number(requestId):null,reason,details};const {error}=await sb.from(table).insert(payload);if(error)throw error}else{const a=demoSafety();a.unshift({id:'S-'+Date.now(),kind:safetyMode,status:'open',provider_id:providerId,request_id:requestId,reason,details,created_at:new Date().toISOString()});saveDemoSafety(a)}addDemoNotification('تم استلام البلاغ','سيتم مراجعة الحالة من فريق خدماتي.','system');setMsg('safetyMsg','تم الإرسال للمراجعة ✓',true);setTimeout(()=>{closeSafetyModal();renderMySafety()},500)}catch(e){setMsg('safetyMsg','تعذر الإرسال الآن. جرّب مرة أخرى.')}}
async function loadMySafety(){if(!BACKEND_READY)return demoSafety().filter(x=>x.user_id===user()?.id||!x.user_id);const [r,d]=await Promise.all([sb.from('reports').select('id,reason,details,status,created_at,provider_id,request_id').eq('reporter_id',sessionUser.id).order('created_at',{ascending:false}).limit(50),sb.from('disputes').select('id,reason,details,status,created_at,provider_id,request_id').eq('user_id',sessionUser.id).order('created_at',{ascending:false}).limit(50)]);if(r.error||d.error)throw r.error||d.error;return [...(r.data||[]).map(x=>({...x,kind:'report'})),...(d.data||[]).map(x=>({...x,kind:'dispute'}))].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at))}
async function renderMySafety(){show('safetyPage');try{const list=await loadMySafety();$('mySafetyList').innerHTML=list.length?list.map(x=>`<article class="safety-row"><div><b>${x.kind==='dispute'?'⚖️ نزاع':'🚩 بلاغ'} · ${escapeHtml(x.reason||'أخرى')}</b><small>رقم ${escapeHtml(x.id)} · ${formatDate(x.created_at)}</small><small>${escapeHtml(x.details||'')}</small></div><span class="trust-badge">${escapeHtml(x.status||'open')}</span></article>`).join(''):'<div class="empty-state"><div>🛡️</div><h3>لا توجد حالات</h3><p>ستظهر البلاغات والنزاعات هنا.</p></div>'}catch(e){$('mySafetyList').innerHTML='<div class="empty-state"><h3>تعذر تحميل الحالات</h3></div>'}}
async function loadAdminSafety(){if(!BACKEND_READY)return demoSafety();const [r,d]=await Promise.all([sb.from('reports').select('*').order('created_at',{ascending:false}).limit(100),sb.from('disputes').select('*').order('created_at',{ascending:false}).limit(100)]);if(r.error||d.error)throw r.error||d.error;return [...(r.data||[]).map(x=>({...x,kind:'report'})),...(d.data||[]).map(x=>({...x,kind:'dispute'}))].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at))}
async function renderAdminSafety(){const box=$('adminSafetyList');if(!box)return;try{const list=await loadAdminSafety();box.innerHTML=list.length?list.map(x=>`<article class="safety-row"><div><b>${x.kind==='dispute'?'⚖️ نزاع':'🚩 بلاغ'} #${escapeHtml(x.id)}</b><small>المستخدم: ${escapeHtml(x.reporter_id||x.user_id||'—')} · الطلب: ${escapeHtml(x.request_id||'—')}</small><small>${escapeHtml(x.reason||'أخرى')} — ${escapeHtml(x.details||'')}</small></div><select class="safety-status" data-kind="${x.kind}" data-id="${escapeHtml(x.id)}"><option value="open" ${x.status==='open'?'selected':''}>مفتوح</option><option value="investigating" ${x.status==='investigating'?'selected':''}>قيد التحقيق</option><option value="resolved" ${x.status==='resolved'?'selected':''}>تم الحل</option><option value="dismissed" ${x.status==='dismissed'?'selected':''}>مرفوض</option></select><span class="risk-badge">مراجعة</span></article>`).join(''):'<div class="empty-state"><div>🛡️</div><h3>لا توجد بلاغات أو نزاعات</h3></div>';box.querySelectorAll('.safety-status').forEach(s=>s.onchange=()=>updateSafetyStatus(s.dataset.kind,s.dataset.id,s.value))}catch(e){box.innerHTML='<div class="empty-state"><h3>تعذر تحميل مركز الأمان</h3></div>'}}
async function updateSafetyStatus(kind,id,status){try{if(BACKEND_READY){const table=kind==='dispute'?'disputes':'reports';const {error}=await sb.from(table).update({status,reviewed_at:status==='resolved'||status==='dismissed'?new Date().toISOString():null}).eq('id',id);if(error)throw error}else{const a=demoSafety().map(x=>x.id===id?{...x,status}:x);saveDemoSafety(a)}toast('تم تحديث الحالة ✓')}catch{toast('تعذر تحديث الحالة')}}
// زر الأمان يظهر للمستخدمين بعد تحميل الصفحة
function addSafetyEntry(){if($('homePage')&&!$('safetyEntryBtn')){const p=document.createElement('div');p.className='panel';p.innerHTML='<div class="section-head"><h2>🛡️ مركز الأمان</h2><button id="safetyEntryBtn" class="secondary">البلاغات والنزاعات</button></div><p class="muted">حماية إضافية للمعاملات ومراجعة أي مشكلة.</p>';const home=$('homePage');const help=home.querySelector('.bottom-help');help?home.insertBefore(p,help):home.appendChild(p);$('safetyEntryBtn').onclick=renderMySafety}}
$('openReportBtn')?.addEventListener('click',()=>openSafetyModal('report'));$('openDisputeBtn')?.addEventListener('click',()=>openSafetyModal('dispute'));$('closeSafetyModal')?.addEventListener('click',closeSafetyModal);$('submitSafetyBtn')?.addEventListener('click',submitSafety);$('safetyBackBtn')?.addEventListener('click',showHome);window.addEventListener('khadamati:login',addSafetyEntry);addSafetyEntry();
