document.querySelectorAll('.admin-tab').forEach(t=>t.addEventListener('click',()=>setTimeout(()=>{if(t.dataset.tab==='safety')renderAdminSafety()},0)));

async function loadProviderTrust(id){
  if(!BACKEND_READY){const p=demoProviders().find(x=>String(x.id)===String(id));return {score:trustScore(p),level:trustLevel(trustScore(p)),risk_penalty:Number(demoTrust()[String(id)]?.risk_penalty||0)}}
  try{const {data,error}=await sb.rpc('provider_trust_score',{p_provider_id:Number(id)});if(error)throw error;return data?.[0]||data||null}catch{return null}
}
async function loadAdminTrust(){
 if(!BACKEND_READY)return demoProviders().map(p=>({provider_id:p.id,name:p.name,score:trustScore(p),level:trustLevel(trustScore(p)),risk_penalty:Number(demoTrust()[String(p.id)]?.risk_penalty||0)}));
 const {data,error}=await sb.rpc('admin_provider_trust'); if(error)throw error; return data||[];
}
async function adjustTrustRisk(id,delta){
 try{if(!BACKEND_READY){const t=demoTrust();const k=String(id);t[k]=t[k]||{};t[k].risk_penalty=Math.max(0,Math.min(25,Number(t[k].risk_penalty||0)+delta));saveDemoTrust(t);toast('تم تحديث مستوى المخاطر');return renderAdminTrust()}
 const {error}=await sb.rpc('admin_adjust_trust_risk',{p_provider_id:Number(id),p_delta:Number(delta)});if(error)throw error;toast('تم تحديث نقاط المخاطر');renderAdminTrust();}catch(e){toast('تعذر تحديث نقاط الثقة')}}
async function renderAdminTrust(){const box=$('adminTrustList');if(!box)return;try{const list=await loadAdminTrust();box.innerHTML=list.length?list.sort((a,b)=>Number(b.score)-Number(a.score)).map(x=>`<article class="trust-admin-row"><div><b>🧑‍💼 ${escapeHtml(x.name||'مقدم خدمة')}</b><small>درجة الثقة: <strong>${Number(x.score||0)}%</strong> · ${escapeHtml(x.level||trustLevel(Number(x.score||0)))}</small><small>خصم المخاطر: ${Number(x.risk_penalty||0)} نقطة</small></div><div class="trust-admin-actions"><button class="secondary trust-minus" data-id="${escapeHtml(x.provider_id||x.id)}">⚠️ +مخاطر</button><button class="secondary trust-plus" data-id="${escapeHtml(x.provider_id||x.id)}">✅ إزالة خطر</button></div></article>`).join(''):'<div class="empty-state"><div>🛡️</div><h3>لا توجد بيانات ثقة</h3></div>';box.querySelectorAll('.trust-minus').forEach(b=>b.onclick=()=>adjustTrustRisk(b.dataset.id,5));box.querySelectorAll('.trust-plus').forEach(b=>b.onclick=()=>adjustTrustRisk(b.dataset.id,-5))}catch(e){box.innerHTML='<div class="empty-state"><h3>تعذر تحميل درجات الثقة</h3></div>'}}


/* V6.2 — التعلم من بيانات السوق: إحصاءات وصفية وآمنة، وليست نموذجًا تنبؤيًا متحيزًا */
async function marketStats(category=''){
  if(!BACKEND_READY){
    const providers=demoProviders().filter(p=>!category||p.category===category);
    const prices=providers.map(p=>Number(p.price||0)).filter(Boolean).sort((a,b)=>a-b);
    const req=(demoUser()?.requestList||[]).filter(r=>!category||r.service===category||r.providerCategory===category);
    const ratings=JSON.parse(localStorage.getItem('khadamatiRatings')||'[]');
    const cats=category?[category]:['تصميم','تسويق','برمجة','صيانة','كتابة','أخرى'];
    const out={};
    for(const c of cats){const ps=demoProviders().filter(p=>p.category===c).map(p=>Number(p.price||0)).filter(Boolean).sort((a,b)=>a-b);const med=ps.length?ps[Math.floor(ps.length/2)]:0;out[c]={providers:ps.length,median:med,min:ps[0]||0,max:ps[ps.length-1]||0,requests:req.filter(r=>r.service===c).length,ratings:ratings.filter(r=>{const p=demoProviders().find(x=>String(x.id)===String(r.providerId));return p?.category===c}).length};}
    return category?out[category]:out;
  }
  const providersQ=category?sb.from('providers').select('id,category,price,verified').eq('active',true).eq('category',category):sb.from('providers').select('id,category,price,verified').eq('active',true);
  const reqQ=category?sb.from('service_requests').select('id,service,provider_price,status').eq('service',category).limit(1000):sb.from('service_requests').select('id,service,provider_price,status').limit(1000);
  const [pr, rq]=await Promise.all([providersQ,rqQ]); if(pr.error||rq.error)throw pr.error||rq.error;
  const groups={};
  for(const p of (pr.data||[])){const c=p.category||'أخرى';groups[c]??={prices:[],providers:0,verified:0,requests:0,completed:0};const g=groups[c];if(Number(p.price)>0)g.prices.push(Number(p.price));g.providers++;if(p.verified)g.verified++;}
  for(const r of (rq.data||[])){const c=r.service||'أخرى';groups[c]??={prices:[],providers:0,verified:0,requests:0,completed:0};groups[c].requests++;if(r.status==='تم التنفيذ')groups[c].completed++;if(Number(r.provider_price)>0)groups[c].prices.push(Number(r.provider_price));}
  for(const g of Object.values(groups)){g.prices.sort((a,b)=>a-b);g.min=g.prices[0]||0;g.max=g.prices[g.prices.length-1]||0;g.median=g.prices.length?g.prices[Math.floor(g.prices.length/2)]:0;}
  return category?(groups[category]||{prices:[],providers:0,verified:0,requests:0,completed:0,min:0,max:0,median:0}):groups;
}
function adaptivePriceFit(price,market){if(!market?.median||!price)return 0;const d=Math.abs(price-market.median)/Math.max(1,market.median);return Math.max(-18,18-d*36)}
let _marketCache=null;
async function smartProviderScoreV62(p,budget,speed){
  const base=smartProviderScore(p,budget,speed);
  try{if(!_marketCache||Date.now()-_marketCache.at>120000){_marketCache={at:Date.now(),data:await marketStats()};}const m=_marketCache.data?.[p.category];return base+adaptivePriceFit(Number(p.price),m)}catch{return base}}
async function renderMarketInsight(){const cat=$('marketCategory')?.value||'';const box=$('marketInsight');if(!box||!cat){if(box)box.innerHTML='';return}box.innerHTML='<div class="market-loading">جاري تحليل البيانات…</div>';try{const m=await marketStats(cat);if(!m.providers&&!m.prices?.length){box.innerHTML='<div class="empty-state"><h3>لا توجد بيانات كافية</h3><p>أضف مزيدًا من مقدمي الخدمات والطلبات لتحسين التقدير.</p></div>';return}const low=m.min||Math.round((m.median||0)*.85),high=m.max||Math.round((m.median||0)*1.15);box.innerHTML=`<div class="market-stat-grid"><div><span>💰</span><b>${m.median||'—'} جنيه</b><small>السعر الوسيط</small></div><div><span>📊</span><b>${low}–${high} جنيه</b><small>النطاق المرصود</small></div><div><span>🧑‍💼</span><b>${m.providers||0}</b><small>مقدمون نشطون</small></div><div><span>📋</span><b>${m.requests||0}</b><small>طلبات مسجلة</small></div></div><p class="market-note">💡 التقدير إحصائي من البيانات المتاحة، وقد يختلف السعر حسب تفاصيل الطلب.</p>`}catch{box.innerHTML='<div class="empty-state"><h3>تعذر تحليل السوق</h3></div>'}}
$('marketAnalyzeBtn')?.addEventListener('click',renderMarketInsight);
$('marketCategory')?.addEventListener('change',renderMarketInsight);
async function renderAdminMarket(){const box=$('adminMarketList');if(!box)return;try{const d=await marketStats();const rows=Object.entries(d).sort((a,b)=>(b[1].requests||0)-(a[1].requests||0));box.innerHTML=rows.length?rows.map(([c,x])=>`<article class="market-admin-row"><div><b>${escapeHtml(c)}</b><small>${x.providers||0} مقدمي خدمة · ${x.requests||0} طلب · ${x.completed||0} مكتملة</small></div><strong>${x.median||'—'} جنيه</strong><span>${x.min||0}–${x.max||0}</span></article>`).join(''):'<div class="empty-state"><h3>لا توجد بيانات كافية</h3></div>'}catch{box.innerHTML='<div class="empty-state"><h3>تعذر تحميل ذكاء السوق</h3></div>'}}
const _renderAdminV62=renderAdmin;renderAdmin=async function(){await _renderAdminV62();const tab=document.querySelector('.admin-tab.active')?.dataset.tab;if(tab==='market')await renderAdminMarket()};
document.querySelectorAll('.admin-tab').forEach(t=>t.addEventListener('click',()=>setTimeout(()=>{if(t.dataset.tab==='market')renderAdminMarket()},0)));


/* V6.3 — سوق العروض والمنافسة */
function demoOfferRequests(){try{return JSON.parse(localStorage.getItem('khadamatiOfferRequests')||'[]')}catch{return []}}
function saveOfferRequests(x){localStorage.setItem('khadamatiOfferRequests',JSON.stringify(x))}
function demoOffers(){try{return JSON.parse(localStorage.getItem('khadamatiOffers')||'[]')}catch{return []}}
function saveOffers(x){localStorage.setItem('khadamatiOffers',JSON.stringify(x))}
async function loadOfferRequests(){
 if(!BACKEND_READY)return demoOfferRequests().map(r=>({...r,offers:demoOffers().filter(o=>String(o.request_id)===String(r.id))}));
 const {data,error}=await sb.from('market_requests').select('id,user_id,service,title,details,budget,deadline_days,status,created_at').eq('status','open').order('created_at',{ascending:false});
 if(error)throw error;
 const ids=(data||[]).map(r=>r.id); let offers=[];
 if(ids.length){const q=await sb.from('service_offers').select('id,request_id,provider_id,price,delivery_days,message,status,created_at,providers(name,price,verified)').in('request_id',ids).order('price',{ascending:true}); if(!q.error)offers=q.data||[]}
 return (data||[]).map(r=>({...r,offers:offers.filter(o=>String(o.request_id)===String(r.id))}));
}
function offerRequestCard(r){
 const offers=(r.offers||[]).slice().sort((a,b)=>Number(a.price)-Number(b.price));
 return `<article class="offer-request-card"><div class="offer-request-top"><div><span class="offer-category">${escapeHtml(r.service)}</span><h3>${escapeHtml(r.title)}</h3></div><span class="offer-open">مفتوح</span></div><p>${escapeHtml(r.details)}</p><div class="offer-meta"><span>💰 حتى ${Number(r.budget||0)?Number(r.budget)+' جنيه':'حسب العرض'}</span><span>⏱️ ${r.deadline_days?Number(r.deadline_days)+' يوم':'مرن'}</span><span>📨 ${offers.length} عروض</span></div><div class="offers-list">${offers.length?offers.map(o=>`<div class="offer-row"><div><b>🧑‍💼 ${escapeHtml(o.providers?.name||o.provider_name||'مقدم خدمة')}</b><small>⭐ ${o.providers?.verified?'موثّق · ':''} ${Number(o.delivery_days||0)} يوم · ${escapeHtml(o.message||'عرض بدون ملاحظة')}</small></div><strong>${Number(o.price||0)} جنيه</strong>${user()?.id&&String(r.user_id)===String(user().id)?`<button class="primary choose-offer" data-request-id="${escapeHtml(r.id)}" data-offer-id="${escapeHtml(o.id)}">اختيار</button>`:''}</div>`).join(''):'<div class="empty-offers">لا توجد عروض حتى الآن — انشر طلبك وانتظر مقدمي الخدمات.</div>'}</div>${user()?.id&&String(r.user_id)===String(user().id)?'<small class="muted">هذا طلبك — اختر العرض الأنسب بعد المقارنة.</small>':''}</article>`
}
async function renderOfferRequests(){const box=$('offerRequestsList');if(!box)return;box.innerHTML='<div class="market-loading">جاري تحميل الطلبات…</div>';try{const list=await loadOfferRequests();box.innerHTML=list.length?list.map(offerRequestCard).join(''):'<div class="empty-state"><div>📣</div><h3>لا توجد طلبات مفتوحة</h3><p>كن أول من ينشر طلبًا في سوق العروض.</p></div>';box.querySelectorAll('.choose-offer').forEach(b=>b.onclick=()=>chooseOffer(b.dataset.requestId,b.dataset.offerId))}catch(e){box.innerHTML='<div class="empty-state"><h3>تعذر تحميل سوق العروض</h3><p>تأكد من إعداد قاعدة البيانات إذا كنت تستخدم الوضع الحقيقي.</p></div>'}}
function openOfferRequestModal(){$('offerRequestModal').classList.remove('hidden');$('offerRequestModal').setAttribute('aria-hidden','false');$('offerTitle').focus()}
function closeOfferRequestModal(){$('offerRequestModal').classList.add('hidden');$('offerRequestModal').setAttribute('aria-hidden','true')}
async function publishOfferRequest(){if(!user())return show('loginPage');const service=$('offerService').value,title=$('offerTitle').value.trim(),details=$('offerDetails').value.trim(),budget=Number($('offerBudget').value||0),deadline=Number($('offerDeadline').value||0);if(!title||!details)return setMsg('offerRequestMsg','اكتب عنوان الطلب والتفاصيل أولاً.');try{if(!BACKEND_READY){const r={id:'MR-'+Date.now().toString().slice(-7),user_id:user().id||'demo',service,title,details,budget,deadline_days:deadline,status:'open',created_at:new Date().toISOString()};const list=demoOfferRequests();list.unshift(r);saveOfferRequests(list);toast('تم نشر طلبك في سوق العروض 🚀')}else{const {data,error}=await sb.from('market_requests').insert({user_id:sessionUser.id,service,title,details,budget:budget||null,deadline_days:deadline||null}).select().single();if(error)throw error;toast('تم نشر الطلب في السوق 🚀')}setMsg('offerRequestMsg','تم نشر الطلب بنجاح ✅',true);setTimeout(()=>{closeOfferRequestModal();renderOfferRequests()},500)}catch(e){setMsg('offerRequestMsg','تعذر نشر الطلب حالياً.')}}
async function submitOffer(requestId){if(!user())return show('loginPage');const price=prompt('اكتب سعر عرضك بالجنيه:');if(price===null)return;const n=Number(price);if(!n||n<=0)return toast('اكتب سعرًا صحيحًا');const days=Number(prompt('مدة التنفيذ بالأيام:', '3')||0);const message=prompt('رسالة مختصرة للعميل (اختياري):','جاهز لتنفيذ الطلب بجودة عالية.')||'';try{if(!BACKEND_READY){const p=demoProviders()[0]||{id:'demo-provider',name:'مقدم خدمة تجريبي'};const arr=demoOffers();arr.push({id:'OFF-'+Date.now(),request_id:requestId,provider_id:p.id,provider_name:p.name,price:n,delivery_days:days||3,message,status:'pending',created_at:new Date().toISOString()});saveOffers(arr);toast('تم إرسال العرض للعميل ✅')}else{const mine=await sb.from('providers').select('id').eq('user_id',sessionUser.id).limit(1).maybeSingle();if(mine.error||!mine.data) return toast('يجب أن يكون لديك ملف مقدم خدمة أولاً');const {error}=await sb.from('service_offers').insert({request_id:Number(requestId),provider_id:mine.data.id,price:n,delivery_days:days||null,message});if(error)throw error;toast('تم إرسال العرض للعميل ✅')}renderOfferRequests()}catch(e){toast('تعذر إرسال العرض')}
}
async function chooseOffer(requestId,offerId){if(!user())return show('loginPage');if(!confirm('تأكيد اختيار هذا العرض؟ سيتم تحويله إلى طلب خدمة ويمكنك دفع قيمته عبر الوساطة.'))return;try{if(!BACKEND_READY){const req=demoOfferRequests().find(r=>String(r.id)===String(requestId));const arr=demoOffers();const selected=arr.find(o=>String(o.id)===String(offerId)&&String(o.request_id)===String(requestId));if(!req||!selected)return toast('العرض غير موجود');arr.forEach(o=>{if(String(o.request_id)===String(requestId))o.status=String(o.id)===String(offerId)?'accepted':'rejected'});saveOffers(arr);const u=demoUser();u.requestList=u.requestList||[];const fee=Number(selected.price)*0.10;const r={id:'KHD-'+Date.now().toString().slice(-6),service:req.service,note:req.title+'\n\n'+req.details,providerId:selected.provider_id,providerName:selected.provider_name||'مقدم خدمة',providerPrice:Number(selected.price),platformFee:fee,providerNet:Number(selected.price)-fee,paymentStatus:'pending',createdAt:new Date().toISOString(),status:'قيد المراجعة',rated:false,sourceMarketRequestId:requestId,agreedDeadlineDays:selected.delivery_days||null};u.requestList.unshift(r);saveDemoUser(u);const reqs=demoOfferRequests();const mr=reqs.find(x=>String(x.id)===String(requestId));if(mr)mr.status='awarded';saveOfferRequests(reqs);addDemoNotification('تم اختيار العرض','تم تحويل العرض إلى طلب خدمة '+r.id+'. يمكنك الآن متابعة الدفع والتنفيذ.','request');toast('تم تحويل العرض إلى طلب خدمة ✅');closeOfferRequestModal()}else{const {data,error}=await sb.rpc('accept_service_offer',{p_request_id:Number(requestId),p_offer_id:Number(offerId)});if(error)throw error;toast('تم تحويل العرض إلى طلب خدمة #'+data+' ✅')}await renderOfferRequests();setTimeout(()=>showRequests(),700)}catch(e){toast('تعذر اختيار العرض حالياً: '+(e.message||''))}}
function showOffers(){if(!user())return show('loginPage');show('offersPage');renderOfferRequests()}
$('offersBackBtn')?.addEventListener('click',showHome);$('publishOfferRequestBtn')?.addEventListener('click',openOfferRequestModal);$('refreshOffersBtn')?.addEventListener('click',renderOfferRequests);$('closeOfferRequestModal')?.addEventListener('click',closeOfferRequestModal);$('offerRequestModal')?.addEventListener('click',e=>{if(e.target.id==='offerRequestModal')closeOfferRequestModal()});$('submitOfferRequestBtn')?.addEventListener('click',publishOfferRequest);
// زر من الصفحة الرئيسية/سوق الخدمات
const offersNavBtn=document.createElement('button');offersNavBtn.className='secondary small-primary';offersNavBtn.textContent='⚔️ سوق العروض';offersNavBtn.onclick=showOffers;document.querySelector('.market-banner')?.appendChild(offersNavBtn);
// إتاحة إرسال عرض من كل طلب سوق مفتوح لمقدمي الخدمات
const _renderOfferRequests=renderOfferRequests;renderOfferRequests=async function(){await _renderOfferRequests();const box=$('offerRequestsList');if(!box)return;box.querySelectorAll('.offer-request-card').forEach(card=>{const top=card.querySelector('.offer-request-top');const id=card.querySelector('.choose-offer')?.dataset.requestId||'';if(id&&user()&&demoProviders().some(p=>String(p.user_id)===String(user().id))){const b=document.createElement('button');b.className='secondary small-primary';b.textContent='💼 أرسل عرضًا';b.onclick=()=>submitOffer(id);top?.appendChild(b)}})};


/* V7.0 shell controller: one-tap navigation without breaking existing flows */
(function(){
  const titles={homePage:['الرئيسية','كل خدماتك في مكان واحد'],providersPage:['الخدمات','اكتشف مقدم الخدمة المناسب'],requestsPage:['طلباتي','تابع الحالة والتنفيذ'],accountPage:['حسابي','إدارة حسابك وخدماتك']};
  function setActive(page){document.querySelectorAll('[data-v7-nav]').forEach(b=>b.classList.toggle('active',b.dataset.v7Nav===page));const t=titles[page]||['خدماتي',''];if($('v7PageTitle'))$('v7PageTitle').textContent=t[0];if($('v7PageHint'))$('v7PageHint').textContent=t[1];}
  function nav(page){if(!user()&&!['publicPage','loginPage','signupPage'].includes(page))return show('loginPage');if(page==='messages'){showRequests();return}show(page);if(page==='providersPage'&&typeof showProviders==='function')showProviders();if(page==='requestsPage'&&typeof showRequests==='function')showRequests();if(page==='accountPage'){const u=user();$('accountName').textContent=u?.name||'حسابك في خدماتي';$('accountPhone').textContent=u?.phone||'إدارة الحساب والمحفظة والأمان من مكان واحد.'}setActive(page);window.scrollTo({top:0,behavior:'smooth'})}
  document.addEventListener('click',e=>{const b=e.target.closest('[data-v7-nav]');if(b)nav(b.dataset.v7Nav);const a=e.target.closest('[data-v7-action]');if(a){const x=a.dataset.v7Action;if(x==='wallet')renderWallet();else if(x==='provider')$('becomeProviderBtn')?.click();else if(x==='referral')renderReferral();else if(x==='safety')renderMySafety();else if(x==='business'){if(typeof showBusiness==='function')showBusiness();else show('businessPage')}else if(x==='logout')$('logoutTop')?.click()}});
  $('v7QuickNotify')?.addEventListener('click',openNotifications);
  $('v7BackTop')?.addEventListener('click',()=>showHome());
  window.addEventListener('khadamati:navigate',e=>{setActive(e.detail.page);$('v7CommandBar')?.classList.toggle('hidden',['loginPage','signupPage','publicPage'].includes(e.detail.page));});
  window.addEventListener('load',()=>{setActive(user()?'homePage':'loginPage');try{const n=JSON.parse(localStorage.getItem('khadamatiRequests')||'[]');if($('v7RequestBadge')&&n.length){$('v7RequestBadge').textContent=n.length;$('v7RequestBadge').classList.remove('hidden')}}catch{}});
})();

/* V7.3 Provider workspace */
(function(){
  function mineProviders(){const u=user(); if(!u)return []; return demoProviders().filter(p=>String(p.user_id||p.userId||'demo')===String(u.id||'demo') || String(p.contact||'')===String(u.phone||''));}
  async function loadMine(){
    if(!BACKEND_READY){const ps=mineProviders(); const req=demoUser()?.requestList||[]; return {providers:ps,requests:req.filter(r=>ps.some(p=>String(p.id)===String(r.providerId)))};}
    const {data:ps,error}=await sb.from('providers').select('id,name,category,description,price,contact,verified,verification_status,commission_rate').eq('user_id',sessionUser.id).order('created_at',{ascending:false}); if(error)throw error;
    const ids=(ps||[]).map(p=>p.id); let requests=[]; if(ids.length){const q=await sb.from('service_requests').select('id,service,note,status,created_at,provider_id,provider_price,platform_fee,provider_net,payment_status').in('provider_id',ids).order('created_at',{ascending:false}); if(q.error)throw q.error; requests=q.data||[];} return {providers:ps||[],requests};
  }
  function pct(r){if(r.status==='تم التنفيذ')return 100;if(r.status==='جاري التنفيذ')return 60;if(r.status==='قيد المراجعة')return 20;return 0}
  async function renderProviderDashboard(){
    if(!user())return show('loginPage'); show('providerDashboardPage');
    const orders=$('providerDashOrders'), offers=$('providerDashOffers'), earn=$('providerDashEarnings');
    orders.innerHTML='<div class="provider-empty">جاري تحميل لوحة العمل…</div>';
    try{const d=await loadMine(); const p=d.providers[0];
      if(!p){$('providerDashProfile').innerHTML='<div class="provider-dash-profile"><div class="avatar">🧑‍💼</div><div><h2>ابدأ كمقدم خدمة</h2><small>أضف أول خدمة لك لتظهر للعملاء وتستقبل الطلبات.</small></div></div>'; $('providerDashStats').innerHTML=''; orders.innerHTML='<div class="provider-empty"><div style="font-size:30px">🚀</div><h3>لا توجد خدمة منشورة</h3><p>اضغط «إضافة خدمة» وابدأ استقبال العملاء.</p><button class="primary" id="pdEmptyAdd">إضافة خدمتي</button></div>'; $('pdEmptyAdd').onclick=()=>$('becomeProviderBtn')?.click(); return;}
      $('providerDashProfile').innerHTML=`<div class="avatar">🧑‍💼</div><div style="flex:1"><h2>${escapeHtml(p.name)}</h2><small>${escapeHtml(p.category)} · ${p.verified?'🛡️ موثق':'التوثيق غير مكتمل'} · يبدأ من ${money(p.price)}</small></div><button class="secondary" id="pdProfileBtn">عرض ملفي</button></div>`;
      const completed=d.requests.filter(r=>r.status==='تم التنفيذ').length, active=d.requests.filter(r=>r.status!=='تم التنفيذ'&&r.status!=='ملغي').length, gross=d.requests.filter(r=>['held','released'].includes(r.payment_status||r.paymentStatus)).reduce((a,r)=>a+Number(r.provider_net||r.providerNet||0),0);
      $('providerDashStats').innerHTML=`<div class="provider-dash-stat"><span>📋</span><strong>${d.requests.length}</strong><small>كل الطلبات</small></div><div class="provider-dash-stat"><span>⚡</span><strong>${active}</strong><small>طلبات نشطة</small></div><div class="provider-dash-stat"><span>✅</span><strong>${completed}</strong><small>مكتملة</small></div><div class="provider-dash-stat"><span>💰</span><strong>${money(gross)}</strong><small>صافي الأرباح</small></div>`;
      $('pdProfileBtn').onclick=()=>showProviderProfile(p.id);
      orders.innerHTML=d.requests.length?d.requests.map(r=>`<article class="provider-order"><div class="provider-order-top"><b>#${escapeHtml(r.id)}</b><span class="status ${statusClass(r.status)}">${escapeHtml(r.status||'قيد المراجعة')}</span></div><h3>${serviceInfo[r.service]?.[0]||'📋'} ${escapeHtml(r.service)}</h3><p>${escapeHtml(r.note||'لا توجد تفاصيل')}</p><div class="provider-progress"><i style="width:${pct(r)}%"></i></div><div class="provider-order-meta"><span>📅 ${formatDate(r.created_at||r.createdAt)}</span><span>💰 ${money(r.provider_net||r.providerNet||0)}</span><span>🔐 ${escapeHtml(r.payment_status||r.paymentStatus||'غير مطلوب')}</span></div><div class="provider-dash-actions"><button class="secondary pd-chat" data-id="${escapeHtml(r.id)}">💬 فتح المحادثة</button><button class="primary pd-exec" data-id="${escapeHtml(r.id)}">🚀 متابعة التنفيذ</button></div></article>`).join(''):'<div class="provider-empty"><div style="font-size:30px">📭</div><h3>لسه مفيش طلبات</h3><p>خدمتك منشورة، وانتظر أول طلب من العملاء.</p></div>';
      orders.querySelectorAll('.pd-chat').forEach(b=>b.onclick=()=>{const r=d.requests.find(x=>String(x.id)===String(b.dataset.id)); if(r)openChat(r)});
      orders.querySelectorAll('.pd-exec').forEach(b=>b.onclick=()=>{const r=d.requests.find(x=>String(x.id)===String(b.dataset.id)); if(r&&typeof openExecution==='function')openExecution(r)});
      offers.innerHTML='<div class="provider-empty"><div style="font-size:28px">💼</div><h3>عروض الأسعار</h3><p>عروضك التي ترسلها للعملاء من سوق العروض تظهر هنا.</p><button class="secondary" id="pdOffersBtn">فتح سوق العروض</button></div>';
      $('pdOffersBtn').onclick=showOffers;
      earn.innerHTML=`<article class="provider-earning-row"><div><b>صافي الأرباح المحررة</b><small>بعد خصم عمولة خدماتي</small></div><strong class="provider-money">${money(gross)}</strong></article><article class="provider-earning-row"><div><b>طلبات مكتملة</b><small>يمكنك متابعة السحب من المحفظة</small></div><strong>${completed}</strong></article><button class="primary" id="pdWalletBtn">💰 فتح المحفظة</button>`; $('pdWalletBtn').onclick=renderWallet;
      document.querySelectorAll('.provider-dash-tab').forEach(t=>t.onclick=()=>{document.querySelectorAll('.provider-dash-tab').forEach(x=>x.classList.remove('active'));t.classList.add('active');['orders','offers','earnings'].forEach(k=>$('providerDash'+k[0].toUpperCase()+k.slice(1)).classList.toggle('hidden',k!==t.dataset.pdTab))});
    }catch(e){orders.innerHTML='<div class="provider-empty"><h3>تعذر تحميل لوحة مقدم الخدمة</h3><p>جرّب مرة أخرى أو راجع إعدادات Supabase.</p></div>'}
  }
  window.renderProviderDashboard=renderProviderDashboard;
  $('providerDashBack')?.addEventListener('click',()=>{show('accountPage');setTimeout(()=>document.querySelector('[data-v7-nav="accountPage"]')?.classList.add('active'),0)});
  $('providerDashAdd')?.addEventListener('click',()=>$('becomeProviderBtn')?.click());
  document.addEventListener('click',e=>{const a=e.target.closest('[data-v72-action="provider-dashboard"]');if(a)renderProviderDashboard()});
  const oldNav=document.querySelector('[data-v7-action="provider"]'); if(oldNav)oldNav.dataset.v7Action='provider-dashboard';
})();


/* V23 — Control Tower */
async function loadV23ControlTower(){
  if(!BACKEND_READY){
    return {metrics:[
      {metric_key:'pending_requests',label:'طلبات قيد المراجعة',value:2,status:'ok',details:'وضع تجريبي'},
      {metric_key:'active_requests',label:'طلبات جاري تنفيذها',value:1,status:'ok',details:'وضع تجريبي'},
      {metric_key:'held_amount',label:'أموال محجوزة',value:0,status:'ok',details:'لا توجد أموال حقيقية في الوضع التجريبي'},
      {metric_key:'reconciliation_issues',label:'مشاكل المطابقة المالية',value:0,status:'ok',details:'وضع تجريبي'},
      {metric_key:'open_reports',label:'بلاغات مفتوحة',value:0,status:'ok',details:'وضع تجريبي'},
      {metric_key:'open_disputes',label:'نزاعات مفتوحة',value:0,status:'ok',details:'وضع تجريبي'}
    ],gates:[{gate_key:'demo',label:'الوضع التجريبي',pass:true,details:'اربط Supabase قبل أي تشغيل مالي حقيقي.'}],incidents:[]};
  }
  const [m,g,i]=await Promise.all([sb.rpc('admin_v23_control_tower'),sb.rpc('admin_v23_launch_gate'),sb.rpc('admin_v23_recent_incidents',{p_limit:20})]);
  if(m.error)throw m.error;if(g.error)throw g.error;if(i.error)throw i.error;
  return {metrics:m.data||[],gates:g.data||[],incidents:i.data||[]};
}
function renderV23ControlTower(d){
  const k=$('adminControlKpis'), gates=$('adminControlGates'), inc=$('adminControlIncidents'); if(!k)return;
  const icon={ok:'🟢',warning:'🟠',critical:'🔴'};
  k.innerHTML=d.metrics.length?d.metrics.map(x=>`<article class="control-kpi ${escapeHtml(x.status||'ok')}"><small>${icon[x.status]||'⚪'} ${escapeHtml(x.label)}</small><b>${['held_amount','released_amount'].includes(x.metric_key)?adminMoney(x.value):Number(x.value||0).toLocaleString('ar-EG')}</b><small>${escapeHtml(x.details||'')}</small></article>`).join(''):'<p class="muted">لا توجد مؤشرات.</p>';
  gates.innerHTML=d.gates.length?d.gates.map(x=>`<div class="control-gate"><div><b>${x.pass?'🟢':'🔴'} ${escapeHtml(x.label)}</b><small>${escapeHtml(x.details||'')}</small></div><strong class="${x.pass?'control-pass':'control-fail'}">${x.pass?'PASS':'BLOCK'}</strong></div>`).join(''):'<p class="muted">لا توجد فحوصات.</p>';
  inc.innerHTML=d.incidents.length?d.incidents.map(x=>`<div class="control-incident"><div><b>${x.severity==='critical'?'🔴':x.severity==='warning'?'🟠':'🔵'} ${escapeHtml(x.title)}</b><small>${escapeHtml(x.details||'')} · ${escapeHtml(x.source||'')}</small></div>${x.resolved?'<span>تم الحل</span>':`<button class="secondary v23-resolve" data-id="${escapeHtml(x.id)}">حل</button>`}</div>`).join(''):'<div class="empty-state"><div>🟢</div><h3>لا توجد حوادث مفتوحة</h3><p>برج التشغيل لا يرى مشاكل حرجة حالياً.</p></div>';
  inc.querySelectorAll('.v23-resolve').forEach(b=>b.onclick=async()=>{try{const r=await sb.rpc('admin_v23_resolve_incident',{p_id:Number(b.dataset.id)});if(r.error)throw r.error;toast('تم إغلاق الحادث ✓');await renderV23Control()}catch{toast('تعذر إغلاق الحادث')}});
}
async function renderV23Control(){const box=$('adminControlKpis');if(!box)return;box.innerHTML='<div class="muted">جاري تحديث برج التشغيل…</div>';try{const d=await loadV23ControlTower();renderV23ControlTower(d)}catch(e){box.innerHTML='<div class="empty-state"><h3>تعذر تحميل برج التشغيل</h3><p>نفّذ V23-control-tower.sql وتأكد من صلاحيات الإدارة.</p></div>'}}
$('adminControlRefresh')?.addEventListener('click',renderV23Control);
const _renderAdminV23=renderAdmin;renderAdmin=async function(){await _renderAdminV23();const tab=document.querySelector('.admin-tab.active')?.dataset.tab;if(tab==='control')await renderV23Control()};
document.querySelectorAll('.admin-tab').forEach(t=>t.addEventListener('click',()=>setTimeout(()=>{if(t.dataset.tab==='control')renderV23Control()},0)));


/* V24 — Controlled Pilot */
async function loadV24Pilot(){
 if(!BACKEND_READY)return {status:{mode:'pilot',payments_enabled:false,withdrawals_enabled:false,new_requests_enabled:true,dispatch_enabled:true,reason:'وضع تجريبي محلي'},gates:[],audit:[]};
 const [s,g,a]=await Promise.all([sb.rpc('v24_platform_status'),sb.rpc('admin_v24_launch_gate'),sb.rpc('admin_v24_recent_control_audit',{p_limit:20})]);
 if(s.error)throw s.error;if(g.error)throw g.error;if(a.error)throw a.error;
 return {status:(s.data||[])[0]||{},gates:g.data||[],audit:a.data||[]};
}
function renderV24Pilot(d){
 const st=$('adminPilotStatus'), act=$('adminPilotActions'), audit=$('adminPilotAudit'); if(!st)return;
 const s=d.status||{};
 st.innerHTML=`<article class="control-kpi ${s.mode==='live'?'ok':s.mode==='paused'?'critical':'warning'}"><small>وضع المنصة</small><b>${escapeHtml(s.mode||'—')}</b><small>${escapeHtml(s.reason||'')}</small></article><article class="control-kpi"><small>💳 الدفع</small><b>${s.payments_enabled?'مفعل':'متوقف'}</b></article><article class="control-kpi"><small>🏦 السحب</small><b>${s.withdrawals_enabled?'مفعل':'متوقف'}</b></article><article class="control-kpi"><small>📋 الطلبات الجديدة</small><b>${s.new_requests_enabled?'مسموح':'متوقف'}</b></article>`;
 act.innerHTML=`<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px"><button class="secondary v24-preset" data-preset="pilot">🧪 وضع تجريبي آمن</button><button class="secondary v24-preset" data-preset="pause">🛑 إيقاف طارئ</button><button class="primary v24-preset" data-preset="live">🚀 وضع Live</button></div><p class="muted">زر Live لا يعني أن بوابة الدفع أصبحت مربوطة؛ يجب إعداد أسرار Gateway واختبارها أولاً.</p>`;
 audit.innerHTML=d.audit.length?d.audit.map(x=>`<div class="control-incident"><div><b>${escapeHtml(x.old_mode||'—')} → ${escapeHtml(x.new_mode||'—')}</b><small>${escapeHtml(x.reason||'بدون سبب')} · ${escapeHtml(String(x.created_at||''))}</small></div><span>${x.payments_enabled?'💳':''}${x.withdrawals_enabled?' 🏦':''}</span></div>`).join(''):'<p class="muted">لا توجد تغييرات.</p>';
 act.querySelectorAll('.v24-preset').forEach(b=>b.onclick=async()=>{const p=b.dataset.preset;const cfg=p==='pilot'?['pilot',false,false,true,true,'إطلاق تجريبي آمن']:p==='pause'?['paused',false,false,false,false,'إيقاف طارئ']:['live',true,true,true,true,'تشغيل Live — بعد التحقق'];if(!BACKEND_READY){toast('الوضع التجريبي المحلي لا يغير قاعدة البيانات');return}try{const r=await sb.rpc('admin_v24_set_platform_control',{p_mode:cfg[0],p_payments_enabled:cfg[1],p_withdrawals_enabled:cfg[2],p_new_requests_enabled:cfg[3],p_dispatch_enabled:cfg[4],p_reason:cfg[5]});if(r.error)throw r.error;toast('تم تحديث وضع المنصة ✓');renderV24Pilot(await loadV24Pilot())}catch(e){toast('تعذر تحديث وضع المنصة')}});
}
async function renderV24Pilot(){const box=$('adminPilotStatus');if(!box)return;box.innerHTML='<div class="muted">جاري فحص الإطلاق…</div>';try{renderV24Pilot(await loadV24Pilot())}catch(e){box.innerHTML='<div class="empty-state"><h3>تعذر تحميل مركز الإطلاق</h3><p>نفّذ V24-controlled-pilot.sql وتأكد من صلاحيات الإدارة.</p></div>'}}
$('adminPilotRefresh')?.addEventListener('click',renderV24Pilot);
const _renderAdminV24=renderAdmin;renderAdmin=async function(){await _renderAdminV24();const tab=document.querySelector('.admin-tab.active')?.dataset.tab;if(tab==='pilot')await renderV24Pilot()};
document.querySelectorAll('.admin-tab').forEach(t=>t.addEventListener('click',()=>setTimeout(()=>{if(t.dataset.tab==='pilot')renderV24Pilot()},0)));
